import ezdxf

doc = ezdxf.readfile('/filesystem/final_batch4__structural_task7_roof_deck_design__blind/output/roof_deck_plan.dxf')
ms = doc.modelspace()

print("=== DXF Layer Analysis ===")
layers = {}
for e in ms:
    layer = e.dxf.layer
    if layer not in layers:
        layers[layer] = {'count': 0, 'types': set()}
    layers[layer]['count'] += 1
    layers[layer]['types'].add(e.dxftype())

for layer, info in sorted(layers.items()):
    print(f"Layer '{layer}': {info['count']} entities, types: {info['types']}")

print("\n=== Checking for required layers ===")
required_layers = ['S-DECK-ZONE', 'S-DECK-TEXT', 'S-FRAMING', 'S-OPENING']
for lr in required_layers:
    present = lr in layers
    print(f"  {lr}: {'PRESENT' if present else 'MISSING'}")

print("\n=== Zone rectangles check ===")
# Look for LWPOLYLINE entities on S-DECK-ZONE
zone_polylines = []
for e in ms:
    if e.dxftype() == 'LWPOLYLINE' and e.dxf.layer == 'S-DECK-ZONE':
        zone_polylines.append(e)
print(f"LWPOLYLINE on S-DECK-ZONE: {len(zone_polylines)}")

# Check if they are closed
for i, pl in enumerate(zone_polylines):
    closed = pl.closed
    print(f"  Rectangle {i+1}: closed={closed}, vertices={len(pl)}")

print("\n=== TEXT labels on S-DECK-TEXT ===")
text_labels = []
for e in ms:
    if e.dxftype() == 'TEXT' and e.dxf.layer == 'S-DECK-TEXT':
        text_labels.append(e)
print(f"TEXT on S-DECK-TEXT: {len(text_labels)}")
for i, txt in enumerate(text_labels):
    print(f"  Label {i+1}: '{txt.text}' at ({txt.dxf.insert[0]:.1f}, {txt.dxf.insert[1]:.1f})")

print("\n=== Openings on S-OPENING ===")
openings = []
for e in ms:
    if e.dxftype() == 'LWPOLYLINE' and e.dxf.layer == 'S-OPENING':
        openings.append(e)
print(f"LWPOLYLINE on S-OPENING: {len(openings)}")
for i, op in enumerate(openings):
    closed = op.closed
    print(f"  Opening {i+1}: closed={closed}, vertices={len(op)}")
